import React from "react";
import {
  BrowserRouter,
  Routes,
  Route,
  Navigate
} from "react-router-dom";

import ProfileLayout from "./components/ProfileLayout";
import CreateProfile from "./components/userProfile";


function App() {
  return (
    <BrowserRouter>

      <Routes>

        <Route path="/" element={<ProfileLayout />}>

          {/* Default page */}
          <Route index element={<Navigate to="create-profile" />} />

          <Route
            path="create-profile"
            element={<CreateProfile />}
          />

        </Route>

      </Routes>

    </BrowserRouter>
  );
}

export default App;
